#include "resident/domains/interaction/interaction_source_projection.hpp"
// 旧visit_messages/1原字节不追加字段；只有显式本人回帖profile才选择这份新独立段。
#include "visit_reply_boundary.hpp"
#include "visit_reply_intents.hpp"
#include <set>
namespace hanmo::resident {
bool visit_reply_command_kind(const StableId& kind){return kind=="reply_visit_message"||kind=="collect_visit_message_reply";}
Outcome<bool>decode_visit_reply_profile(const BoundaryValue&s,const std::vector<StableId>&caps){auto selected=decode_visit_reply_profile_version(s,caps);return selected.ok?Outcome<bool>{true,selected.value!=0,{}}:Outcome<bool>{false,{},selected.error};}
Status validate_visit_reply_layout(const CommonStore&common,const std::vector<std::pair<StableId,StableId>>&modules,const VisitReplyCatalog*catalog,const VisitReplyState*state,const VisitReplyIntentCatalog*intents){Integer count=0,version=0,original_count=0,original=0,authored=0,reception=0,claims=0;for(const auto&m:modules){if(m.first==visit_reply_module){++count;if(m.second=="1")version=1;else if(m.second=="2")version=2;else if(m.second=="3")version=3;else if(m.second=="4")version=4;else return common_failure("UnsupportedVisitReplyVersion");}if(m.first=="visit_messages"){++original_count;if(m.second=="1")original=1;else if(m.second=="2")original=2;else if(m.second=="3")original=3;else return common_failure("UnsupportedVisitMessageVersion");}if(m.first==visit_reply_intent_module){++authored;if(m.second!="1")return common_failure("UnsupportedVisitReplyIntentVersion");}if(m.first=="visit_reception_intents"&&m.second=="1")++reception;if(m.first==visit_reception_claim_module&&m.second=="1")++claims;}const bool needs_authored=visit_reply_authored_version(version);const bool original_ok=original_count==1&&(visit_reply_life_version(version)?(original==2||original==3):original==1);if(count!=(catalog?1:0)||bool(catalog)!=bool(state)||(catalog&&(catalog->version!=version||!original_ok))||(state&&state->version!=version)||authored!=(needs_authored?1:0)||bool(intents)!=needs_authored||(intents&&(intents->version!=1||reception!=1||claims!=1)))return common_failure("VisitReplyProfileMismatch");if(state)return common_success();for(const auto&h:common.state().facts.rows())if(h.second.domain==visit_reply_module||h.second.kind==visit_reply_posted_kind||h.second.kind==visit_reply_collected_kind)return common_failure("VisitReplyProfileRequired",h.first);return validate_visit_reply_cached_results(common,nullptr);}
Outcome<bool> emit_visit_reply_fact_payload_fields(ProjectionWriter& w,const VisitReplyState* state,const FactRecord& h){const bool own=h.kind==visit_reply_posted_kind||h.kind==visit_reply_collected_kind;if(!own&&h.domain!=visit_reply_module)return {true,false,{}};if(!own||!state||h.domain!=visit_reply_module)return {false,{},common_failure("VisitReplyFactMismatch",h.id).error};auto status=emit_visit_reply_fact_fields(w,*state,h.id,&h);if(!status.ok)return {false,{},status.error};return {w.status().ok,w.status().ok,w.status().error};}
Status emit_visit_reply_fact_payloads_fields(ProjectionWriter& w,const CommonStore& common,const VisitReplyState* state){std::size_t count=0;for(const auto& row:common.state().facts.rows()){const auto& h=row.second;const bool own=h.kind==visit_reply_posted_kind||h.kind==visit_reply_collected_kind;if(!own&&h.domain!=visit_reply_module)continue;if(!own||!state||h.id!=row.first||h.domain!=visit_reply_module)return common_failure("VisitReplyFactMismatch",row.first);auto checked=w.object(row.first,h.field_order,[&](auto&out){return emit_visit_reply_fact_fields(out,*state,row.first,&h);});if(!checked.ok)return checked;++count;}if(state&&count!=state->posted.size()+state->collected.size())return common_failure("VisitReplyFactCoverageMismatch");return w.status();}
Outcome<BoundaryValue> visit_reply_fact_payloads(const CommonStore& common,const VisitReplyState* state){BoundaryValue value;BoundaryProjectionWriter writer(value);auto checked=writer.object("",[&](auto&out){return emit_visit_reply_fact_payloads_fields(out,common,state);});if(checked.ok)checked=writer.finish();return checked.ok?Outcome<BoundaryValue>{true,std::move(value),{}}:Outcome<BoundaryValue>{false,{},checked.error};}
Status validate_visit_reply_json_payloads(const CommonStore& common,const VisitReplyState* state,const BoundaryValue& value){try{using namespace boundary;auto expected=visit_reply_fact_payloads(common,state);if(!expected.ok)return {false,{},expected.error};for(const auto& row:object(expected.value,"visit_message_replies/facts")){const auto& actual=field(field(value,"facts","state"),row.first,"facts");if(!compare_boundary(actual,row.second).exact())return common_failure("VisitReplyFactPayloadMismatch",row.first);}return common_success();}catch(const boundary::DecodeFailure& e){return {false,{},e.error};}}
}
